174		if err != nil {
175			return fmt.Errorf("failed to load settings: %w", err)
176		}
177		if s.SummaryGeneration == nil {
178			s.SummaryGeneration = &settings.SummaryGenerationSettings{}
179		}
180	
181		if provider != "" {
182			if err := validateSummaryProvider(provider); err != nil {
183				return err
184			}
185			if ag, getErr := getSummaryAgent(types.AgentName(provider)); getErr == nil && external.IsExternal(ag) {
186				if !s.ExternalAgents {
187					s.ExternalAgents = true
188					fmt.Fprintln(w, externalAgentsAutoEnabledNotice)
189				}
190			}
191		}
192		if model != "" && provider == "" && s.SummaryGeneration.Provider == "" {
193			// The target file alone has no provider, but the merged runtime
194			// settings might (e.g. provider in project, model override in local).
195			// Check the full merged view before rejecting.
196			merged, mergeErr := settings.Load(ctx)
197			if mergeErr != nil || merged.SummaryGeneration == nil || merged.SummaryGeneration.Provider == "" {
198				return errors.New("--summarize-model requires an existing summary provider or --summarize-provider")
199			}
