205			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
206				return fmt.Errorf("failed to save settings: %w", err)
207			}
208		} else {
209			if err := SaveEntireSettings(ctx, s); err != nil {
210				return fmt.Errorf("failed to save settings: %w", err)
211			}
