119	func computeCheckpointDiff(a, b *checkpoint.CheckpointSummary) *checkpointDiff {
120		out := &checkpointDiff{
121			A:                a,
122			B:                b,
123			AID:              a.CheckpointID.String(),
124			BID:              b.CheckpointID.String(),
125			ACheckpoints:     a.CheckpointsCount,
126			BCheckpoints:     b.CheckpointsCount,
127			CheckpointsDelta: b.CheckpointsCount - a.CheckpointsCount,
128		}
129	
130		aFiles := make(map[string]struct{}, len(a.FilesTouched))
131		for _, f := range a.FilesTouched {
132			aFiles[f] = struct{}{}
133		}
134		bFiles := make(map[string]struct{}, len(b.FilesTouched))
135		for _, f := range b.FilesTouched {
136			bFiles[f] = struct{}{}
137		}
138		for f := range bFiles {
139			if _, ok := aFiles[f]; !ok {
140				out.FilesAdded = append(out.FilesAdded, f)
141			}
142		}
143		for f := range aFiles {
144			if _, ok := bFiles[f]; !ok {
145				out.FilesRemoved = append(out.FilesRemoved, f)
146			}
147		}
148		sort.Strings(out.FilesAdded)
149		sort.Strings(out.FilesRemoved)
150	
151		if a.TokenUsage != nil || b.TokenUsage != nil {
152			var aIn, aOut, aCR, aCW int
153			var bIn, bOut, bCR, bCW int
154			if a.TokenUsage != nil {
155				aIn = a.TokenUsage.InputTokens
156				aOut = a.TokenUsage.OutputTokens
157				aCR = a.TokenUsage.CacheReadTokens
158				aCW = a.TokenUsage.CacheCreationTokens
159			}
160			if b.TokenUsage != nil {
161				bIn = b.TokenUsage.InputTokens
162				bOut = b.TokenUsage.OutputTokens
163				bCR = b.TokenUsage.CacheReadTokens
164				bCW = b.TokenUsage.CacheCreationTokens
165			}
166			out.TokensDelta = tokenDelta{
167				Total:      (bIn + bOut + bCR + bCW) - (aIn + aOut + aCR + aCW),
168				Input:      bIn - aIn,
169				Output:     bOut - aOut,
170				CacheRead:  bCR - aCR,
171				CacheWrite: bCW - aCW,
172			}
173		}
174	
175		return out
176	}
