178	func writeCheckpointDiffText(w io.Writer, d *checkpointDiff) error {
179		var sb strings.Builder
180		fmt.Fprintf(&sb, "Diff: %s → %s\n", d.AID, d.BID)
181		fmt.Fprintf(&sb, "\nCheckpoints:     %+d (%d → %d)\n", d.CheckpointsDelta, d.ACheckpoints, d.BCheckpoints)
182	
183		sb.WriteString("\nTokens:\n")
184		fmt.Fprintf(&sb, "  total:        %+d\n", d.TokensDelta.Total)
185		fmt.Fprintf(&sb, "  input:        %+d\n", d.TokensDelta.Input)
186		fmt.Fprintf(&sb, "  output:       %+d\n", d.TokensDelta.Output)
187		fmt.Fprintf(&sb, "  cache_read:   %+d\n", d.TokensDelta.CacheRead)
188		fmt.Fprintf(&sb, "  cache_write:  %+d\n", d.TokensDelta.CacheWrite)
189	
190		if len(d.FilesAdded) > 0 {
191			fmt.Fprintf(&sb, "\nFiles added (%d):\n", len(d.FilesAdded))
192			for _, f := range d.FilesAdded {
193				sb.WriteString("  + " + f + "\n")
194			}
195		}
196		if len(d.FilesRemoved) > 0 {
197			fmt.Fprintf(&sb, "\nFiles removed (%d):\n", len(d.FilesRemoved))
198			for _, f := range d.FilesRemoved {
199				sb.WriteString("  - " + f + "\n")
200			}
201		}
202		if len(d.FilesAdded) == 0 && len(d.FilesRemoved) == 0 {
203			sb.WriteString("\nFiles touched: identical set.\n")
204		}
205	
206		if _, err := io.WriteString(w, sb.String()); err != nil {
207			return fmt.Errorf("write diff: %w", err)
208		}
209		return nil
210	}
